    if (/(our team|founder|founded|since 20)/i.test(allText)) s += 1;
    if (BIG.test(r.company + ' ' + host)) s -= 3;
    r.persona_score = String(Math.max(1, Math.min(10, s)));
  }
  r.note = (r.note ? r.note + ' | ' : '') + 'enriched ' + todayStr();
}
