const TEST_ADDRESS = '';                // <-- your own email for test sends (required while TEST_MODE is true)
const TEST_COUNT = 2;                   // how many sample emails to send in test mode
const DAILY_LIMIT = 10;                 // real sends per day
const SENDER_NAME = '[YOUR NAME]';
const SENDER_ROLE = '[YOUR ROLE]';
const SENDER_COMPANY = '[YOUR COMPANY]';
const SERVICE_LINE = '[ONE SENTENCE: what your team does, e.g. "We build websites for agencies under their own brand."]';
const OFFER = '[ONE-SENTENCE OFFER: what you deliver, for whom, and the price/turnaround hook]';
// ============================================================================

const rows = $('4 Sender - Parse Inbox').all().map(i => clean(i.json)).filter(r => r && r.lead_id);
const sent = $('4 Sender - Parse Sent Log').all().map(i => clean(i.json)).filter(r => r && r.email);
const sentSet = new Set(sent.map(r => r.email.toLowerCase()));
const sentToday = sent.filter(r => r.sent_date === todayStr()).length;

if (TEST_MODE && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(TEST_ADDRESS)) {
  throw new Error('TEST_MODE is on: set TEST_ADDRESS (your own email) in this node first.');
}
const placeholders = [SENDER_NAME, SENDER_ROLE, SENDER_COMPANY, SERVICE_LINE, OFFER].some(v => v.includes('['));
if (!TEST_MODE && placeholders) {
  throw new Error('Fill in SENDER_NAME, SENDER_ROLE, SENDER_COMPANY, SERVICE_LINE and OFFER before sending to real leads.');
}

const remaining = TEST_MODE ? TEST_COUNT : Math.max(0, DAILY_LIMIT - sentToday);
const queue = rows
  .filter(r => r.status === 'approved' && r.email && !sentSet.has(r.email.toLowerCase()))
  .sort((a, b) => (parseFloat(b.persona_score) || 0) - (parseFloat(a.persona_score) || 0))
  .slice(0, remaining);

const out = queue.map(r => {
  const first = r.first_name ? r.first_name : 'there';
  const subject = `Overflow design/dev capacity for ${r.company}`;
  const html = `<p>Hi ${first},</p>
<p>I'm ${SENDER_NAME} (${SENDER_ROLE}, ${SENDER_COMPANY}). ${SERVICE_LINE}</p>
<p>${OFFER}</p>
<p>If ${r.company} ever has overflow work or a project you'd rather not staff in-house, I'd be glad to do a small free sample so you can judge the quality first. Worth a quick reply?</p>
<p>Best,<br>${SENDER_NAME}<br>${SENDER_ROLE}, ${SENDER_COMPANY} | [YOUR WEBSITE]</p>
<p style="color:#777;font-size:12px">You're receiving this because ${r.company} is listed as a digital agency. If you'd rather not hear from us, just reply "no" and I won't contact you again.</p>`;
  return { json: { lead_id: r.lead_id, email: r.email, company: r.company, first_name: r.first_name || '', testMode: TEST_MODE, to: TEST_MODE ? TEST_ADDRESS : r.email, subject: (TEST_MODE ? `[TEST for ${r.email}] ` : '') + subject, html } };
});
console.log('Batch size', out.length, 'sentToday', sentToday, 'testMode', TEST_MODE);
return out;

