const msg = $input.first().json;
let addr = '';
try {
  if (msg.from && msg.from.value && msg.from.value.length) addr = msg.from.value[0].address;
  else if (typeof msg.from === 'string') addr = msg.from;
  else if (msg.from && msg.from.text) addr = msg.from.text;
} catch (e) {}
const match = (addr || '').match(/[^<\s]+@[^>\s]+/);
addr = match ? match[0].toLowerCase() : (addr || '').toLowerCase();
const isBounce = /(mailer-daemon|postmaster)/i.test(addr) || /(undeliver|delivery status|returned mail|failure notice|delivery has failed)/i.test(msg.subject || '');
const text = String(msg.text || msg.textPlain || msg.html || '').slice(0, 8000).toLowerCase();
return [{ json: { senderEmail: addr, isBounce, text, subject: msg.subject || '', receivedDate: msg.date || new Date().toISOString() } }];

const clean = (r) => { const o = {}; for (const k of Object.keys(r || {})) o[k.replace(/^\ufeff/, '')] = r[k]; return o; };
const s = $('5 Replies - Extract Sender').first().json;
const senderEmail = s.senderEmail;
const today = new Date().toISOString().slice(0,10);
const rows = $input.all().map(item => clean(item.json)).filter(r => r.email);
for (const row of rows) {
  const e = (row.email || '').toLowerCase();
  if (row.replied) continue;
  if (s.isBounce) {
    if (e && s.text.includes(e)) { row.replied = 'bounced'; row.replied_date = today; }
  } else if (e === senderEmail) {
    row.replied = 'yes';
    row.replied_date = today;
  }
}
return rows.length ? rows.map(r => ({ json: r })) : [{ json: { email: '', company: '', first_name: '', sent_date: '', follow_up_1_sent: '', replied: '', replied_date: '' } }];

const FOLLOW_UPS_ENABLED = false;   // set to true once the follow-up copy in 'Send Follow-up Email' is written
if (!FOLLOW_UPS_ENABLED) return [];
const clean = (r) => { const o = {}; for (const k of Object.keys(r || {})) o[k.replace(/^\ufeff/, '')] = r[k]; return o; };
const FOLLOW_UP_AFTER_DAYS = 3;
const msPerDay = 24 * 60 * 60 * 1000;
const today = new Date();
const candidates = [];
for (const item of $input.all()) {
  const row = clean(item.json);
  if (!row.email || !row.sent_date) continue;
  if (row.replied) continue;
  if (row.follow_up_1_sent) continue;
  const sentDate = new Date(row.sent_date);
  if (isNaN(sentDate.getTime())) continue;
  const daysSince = Math.floor((today.getTime() - sentDate.getTime()) / msPerDay);
  if (daysSince >= FOLLOW_UP_AFTER_DAYS) {
    candidates.push({ json: row });
  }
}
return candidates;

const clean = (r) => { const o = {}; for (const k of Object.keys(r || {})) o[k.replace(/^\ufeff/, '')] = r[k]; return o; };
